#!/usr/bin/env python3
import json
import re

def parse_routes(input_file, output_file):
    routes = []
    current_route = None
    state = "OUTSIDE"  # State machine states: OUTSIDE, INSIDE_ROUTE, INSIDE_METHOD, INSIDE_LIMIT

    with open(input_file, 'r') as f:
        for line in f:
            line = line.strip()

            if not line:
                continue

            # State: OUTSIDE - looking for <route ...>
            if line.startswith("<route "):
                # Extract path from <route /path>
                match = re.match(r'<route\s+(\S+)>', line)
                if match:
                    current_route = {
                        "path": match.group(1),
                        "method": None,
                        "limit": None
                    }
                    state = "INSIDE_ROUTE"

            elif line == "</route>":
                if current_route is not None:
                    routes.append(current_route)
                    current_route = None
                state = "OUTSIDE"

            elif state == "INSIDE_ROUTE" and line.startswith("method "):
                # Extract method
                match = re.match(r"method\s+(\S+)", line)
                if match:
                    current_route["method"] = match.group(1)
                    state = "INSIDE_METHOD"

            elif state == "INSIDE_METHOD" and line.startswith("limit "):
                # Extract limit
                match = re.match(r"limit\s+(\d+)", line)
                if match:
                    current_route["limit"] = int(match.group(1))
                    state = "INSIDE_LIMIT"
                # If there's no limit line, stay in method state but that's invalid

    # Write JSON output
    with open(output_file, 'w') as f:
        json.dump(routes, f, indent=2)

if __name__ == "__main__":
    parse_routes("/home/user/route.conf", "/home/user/routes.json")
