#include <iostream>
#include <fstream>
#include <string>
#include <sstream>
#include "fastmath.h"

void process_line(const std::string& line) {
    size_t deg_pos = line.find("DEG: ");
    size_t coeff_pos = line.find("| COEFFS: ");
    size_t x_pos = line.find("| X: ");

    if (deg_pos == std::string::npos || coeff_pos == std::string::npos || x_pos == std::string::npos) return;

    int degree = std::stoi(line.substr(deg_pos + 5, coeff_pos - (deg_pos + 5)));

    // FIX: degree + 1 coefficients (a polynomial of degree N has N+1 coefficients)
    double* coeffs = new double[degree + 1]; 

    // FIX: remove the -1 that was cutting off the last character
    std::string c_str = line.substr(coeff_pos + 10, x_pos - (coeff_pos + 10)); 

    std::stringstream ss(c_str);
    std::string item;
    int idx = 0;
    while(std::getline(ss, item, ',')) {
        coeffs[idx++] = std::stod(item);
    }

    double x = std::stod(line.substr(x_pos + 5));

    double result = 0;
    // FIX: loop condition - array size is degree + 1, so iterate 0 to degree inclusive
    for(int i = 0; i <= degree; ++i) { 
        result += coeffs[i] * fast_pow(x, i);
    }

    std::cout << result << "\n";
    // FIX: delete allocated memory
    delete[] coeffs;
}

int main() {
    std::ifstream in("input.txt");
    std::string line;
    while(std::getline(in, line)) {
        process_line(line);
    }
    return 0;
}
