use std::fs::{self, File};
use std::io::{Read, Write};
use std::path::{Path, PathBuf};

fn main() {
    // Create output directories if they don't exist
    fs::create_dir_all("/home/user/processed").expect("Failed to create processed dir");
    fs::create_dir_all("/home/user/links").expect("Failed to create links dir");

    // Find all .log files recursively
    let mut files = Vec::new();
    collect_log_files("/home/user/dataset/", &mut files);

    for file_path in files {
        // Read the file as bytes
        let bytes = match fs::read(&file_path) {
            Ok(b) => b,
            Err(e) => {
                eprintln!("Failed to read {:?}: {}", file_path, e);
                continue;
            }
        };

        // Decode UTF-16LE
        let text = match decode_utf16le(&bytes) {
            Ok(t) => t,
            Err(e) => {
                eprintln!("Failed to decode {:?}: {}", file_path, e);
                continue;
            }
        };

        // Replace ERROR_CODE_99 with RESOLVED_01
        let transformed = text.replace("ERROR_CODE_99", "RESOLVED_01");

        // Get the basename
        let basename = file_path.file_name()
            .and_then(|name| name.to_str())
            .expect("Invalid filename");

        // Write to processed directory (with full path)
        let output_path = PathBuf::from("/home/user/processed").join(basename);
        if let Err(e) = fs::write(&output_path, &transformed) {
            eprintln!("Failed to write {:?}: {}", output_path, e);
            continue;
        }

        // Create hard link in links directory (same basename)
        let link_path = PathBuf::from("/home/user/links").join(basename);
        if let Err(e) = fs::hard_link(&output_path, &link_path) {
            eprintln!("Failed to create hard link {:?}: {}", link_path, e);
            continue;
        }
    }
}

fn collect_log_files(dir: &str, files: &mut Vec<PathBuf>) {
    let entries = match fs::read_dir(dir) {
        Ok(entries) => entries,
        Err(_) => return,
    };

    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            collect_log_files(&path.to_string_lossy(), files);
        } else if path.extension().map_or(false, |ext| ext == "log") {
            files.push(path.clone());
        }
    }
}

fn decode_utf16le(bytes: &[u8]) -> Result<String, String> {
    if bytes.len() % 2 != 0 {
        return Err("Invalid UTF-16LE: odd number of bytes".to_string());
    }

    let mut chars = Vec::new();
    for chunk in bytes.chunks(2) {
        let code_unit = u16::from_le_bytes([chunk[0], chunk[1]]);
        chars.push(code_unit);
    }

    String::from_utf16(&chars).map_err(|e| e.to_string())
}
