package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
)

type Query struct {
	ID   string `json:"id"`
	Path []string `json:"path"`
}

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintf(os.Stderr, "Usage: %s <input_file.jsonl>\n", os.Args[0])
		os.Exit(1)
	}

	file, err := os.Open(os.Args[1])
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error opening file: %v\n", err)
		os.Exit(1)
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		line := scanner.Text()
		if line == "" {
			continue
		}

		var query Query
		if err := json.Unmarshal([]byte(line), &query); err != nil {
			// Invalid JSON, skip
			continue
		}

		if isValidQuery(query) {
			fmt.Println(query.ID)
		}
	}
}

func isValidQuery(q Query) bool {
	path := q.Path

	// Path must have odd length (node, edge, node, ..., node)
	if len(path) == 0 || len(path)%2 == 0 {
		return false
	}

	// Calculate depth (number of edges)
	depth := len(path) / 2 // integer division gives number of edges for odd-length path
	if depth > 3 {
		return false
	}

	// Validate each edge
	// path[0] is a node, path[1] is edge, path[2] is node, etc.
	for i := 0; i < len(path); i += 2 {
		if i+2 > len(path) {
			// This shouldn't happen with odd length check above, but safety
			break
		}
		nodeStart := path[i]
		nodeEnd := path[i+2]
		edge := path[i+1]

		// Check if the edge is allowed and connects the correct nodes
		if !isAllowedEdge(nodeStart, edge, nodeEnd) {
			return false
		}
	}

	return true
}

func isAllowedEdge(node, edge, nextNode string) bool {
	// Define allowed edges based on schema
	switch edge {
	case "Bought":
		if node == "User" && nextNode == "Product" {
			return true
		}
		return false
	case "Follows":
		if node == "User" && nextNode == "User" {
			return true
		}
		return false
	case "SimilarTo":
		if node == "Product" && nextNode == "Product" {
			return true
		}
		return false
	default:
		return false
	}
}
