use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::error::Error;
use std::fs::File;
use std::io::{BufRead, BufReader, Write};

#[derive(Debug, Deserialize)]
struct Event {
    timestamp: u64,
    service: String,
    change_id: String,
    payload_size: u64,
}

#[derive(Debug, Serialize)]
struct Violation {
    service: String,
    timestamp: u64,
    change_id: String,
}

fn main() -> Result<(), Box<dyn Error>> {
    // Open the input JSONL file
    let file = File::open("/home/user/config_events.jsonl")?;
    let reader = BufReader::new(file);

    // BTreeMap keeps services sorted alphabetically by key
    let mut events_by_service: BTreeMap<String, Vec<Event>> = BTreeMap::new();

    // Stream and parse events
    for line_result in reader.lines() {
        let line = line_result?;
        if line.trim().is_empty() {
            continue;
        }

        let event: Event = serde_json::from_str(&line)?;
        events_by_service
            .entry(event.service.clone())
            .or_insert_with(Vec::new)
            .push(event);
    }

    // Collect violations
    let mut violations: Vec<Violation> = Vec::new();

    // Process each service's events
    for (_service_name, mut service_events) in events_by_service {
        // Sort events by timestamp (ascending)
        service_events.sort_by_key(|e| e.timestamp);

        // Apply validation quality gate
        let mut last_timestamp: Option<u64> = None;
        for event in service_events {
            if let Some(prev_ts) = last_timestamp {
                let diff_ms = event.timestamp as i64 - prev_ts as i64;
                if diff_ms < 1000 {
                    // Violation: less than 1000ms since last change
                    violations.push(Violation {
                        service: event.service.clone(),
                        timestamp: event.timestamp,
                        change_id: event.change_id.clone(),
                    });
                }
            }
            last_timestamp = Some(event.timestamp);
        }
    }

    // Sort violations: by service name (alphabetical Unicode), then by timestamp
    violations.sort_by(|a, b| {
        a.service
            .cmp(&b.service)
            .then_with(|| a.timestamp.cmp(&b.timestamp))
    });

    // Write violations to CSV
    let mut csv_file = File::create("/home/user/invalid_changes.csv")?;

    // Write header
    writeln!(csv_file, "service,timestamp,change_id")?;

    // Write violations
    for violation in &violations {
        writeln!(
            csv_file,
            "{},{},{}",
            violation.service, violation.timestamp, violation.change_id
        )?;
    }

    println!("Processed events. Found {} violations.", violations.len());
    Ok(())
}
