package graphdb

import "container/heap"

type Edge struct {
	Target string
	Weight int
}

type GraphStore struct {
	allEdges  []struct{ Source string; E Edge }
	edgeIndex map[string][]Edge
}

func NewGraphStore() *GraphStore {
	return &GraphStore{
		allEdges:  make([]struct{ Source string; E Edge }, 0),
		edgeIndex: make(map[string][]Edge),
	}
}

func (s *GraphStore) AddEdge(source, target string, weight int) {
	e := Edge{Target: target, Weight: weight}
	s.allEdges = append(s.allEdges, struct{ Source string; E Edge }{source, e})
	s.edgeIndex[source] = append(s.edgeIndex[source], e)
}

func (s *GraphStore) GetEdges(nodeID string) []Edge {
	// Use the pre-built index for O(1) lookups
	if edges, ok := s.edgeIndex[nodeID]; ok {
		return edges
	}
	return nil
}

type Item struct {
	node string
	cost int
	index int
}

type PriorityQueue []*Item

func (pq PriorityQueue) Len() int { return len(pq) }
func (pq PriorityQueue) Less(i, j int) bool { return pq[i].cost < pq[j].cost }
func (pq PriorityQueue) Swap(i, j int) {
	pq[i], pq[j] = pq[j], pq[i]
	pq[i].index = i
	pq[j].index = j
}
func (pq *PriorityQueue) Push(x interface{}) {
	n := len(*pq)
	item := x.(*Item)
	item.index = n
	*pq = append(*pq, item)
}
func (pq *PriorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	item := old[n-1]
	item.index = -1
	*pq = old[0 : n-1]
	return item
}

type PathNode struct {
	Node   string
	Weight int
}

func (s *GraphStore) ShortestPath(start, end string) []PathNode {
	dist := make(map[string]int)
	prev := make(map[string]string)
	weightTo := make(map[string]int)

	pq := make(PriorityQueue, 0)
	heap.Init(&pq)

	dist[start] = 0
	heap.Push(&pq, &Item{node: start, cost: 0})

	for pq.Len() > 0 {
		curr := heap.Pop(&pq).(*Item)
		u := curr.node

		if u == end {
			break
		}

		if curr.cost > dist[u] {
			continue
		}

		edges := s.GetEdges(u)
		for _, edge := range edges {
			v := edge.Target
			alt := dist[u] + edge.Weight

			if d, ok := dist[v]; !ok || alt < d {
				dist[v] = alt
				prev[v] = u
				weightTo[v] = edge.Weight
				heap.Push(&pq, &Item{node: v, cost: alt})
			}
		}
	}

	if _, ok := dist[end]; !ok && start != end {
		return nil
	}

	var path []string
	curr := end
	for curr != "" {
		path = append([]string{curr}, path...)
		curr = prev[curr]
	}

	var res []PathNode
	for i, node := range path {
		w := 0
		if i > 0 {
			w = weightTo[node]
		}
		res = append(res, PathNode{Node: node, Weight: w})
	}

	return res
}
