use csv::Writer;

#[derive(Debug, Deserialize)]
struct User {
    user_id: i32,
    age: Option<i32>,  // Can be None if value is empty string
    signup_source: String,
}

#[derive(Debug, Deserialize)]
struct Event {
    event_id: i32,
    user_id: i32,
    score: f64,
}

#[derive(Debug, Serialize)]
struct OutputRow {
    event_id: i32,
    user_id: i32,
    age: i32,  // Imputed (0) if missing, so always integer
    signup_source: String,
    score_normalized: i32,
}

