    // Read users.csv
    let users_file = File::open("/home/user/data/users.csv")?;
    let mut users_reader = csv::Reader::from_reader(users_file);

    // Collect users into a HashMap for efficient lookup
    let mut users_map: HashMap<i32, User> = HashMap::new();
    for result in users_reader.deserialize() {
        let user: User = result?;
        users_map.insert(user.user_id, user);
    }

    // Read events.csv
    let events_file = File::open("/home/user/data/events.csv")?;
    let mut events_reader = csv::Reader::from_reader(events_file);

    // Join and process
    let mut output_rows: Vec<(i32, i32, i32, String, i32)> = Vec::new(); // event_id, user_id, age, signup_source, score_normalized

    for result in events_reader.deserialize() {
        let event: Event = result?;

        // Inner join: only include events with matching user_id in users
        if let Some(user) = users_map.get(&event.user_id) {
