#!/usr/bin/env python3
import sys
import json
import gzip
import binascii

def parse_wal(filepath):
    """Parse WAL log files and return list of transaction objects."""

    # Determine file type and read content
    if filepath.endswith('.gz'):
        try:
            with gzip.open(filepath, 'rb') as f:
                content = f.read()
        except Exception:
            return []
    else:
        try:
            with open(filepath, 'rb') as f:
                content = f.read()
        except Exception:
            return []

    # Decode as UTF-8
    text = content.decode('utf-8')

    transactions = []
    in_txn = False
    current_txn = None
    current_encoding = None
    payload_lines = []

    lines = text.split('\n')

    for line in lines:
        if in_txn:
            if line.startswith('[WAL_END] '):
                # End of transaction
                if ' ' in line:
                    end_txn = line.split(' ', 1)[1]
                else:
                    end_txn = line[len('[WAL_END]'):]

                if end_txn == current_txn:
                    # Only process if previous encoding was set or handle appropriately
                    payload_str = '\n'.join(payload_lines)
                    if current_encoding == 'utf-16le':
                        # Hex decode and UTF-16LE decode
                        hex_content = payload_str.replace('\n', '')
                        try:
                            payload_bytes = binascii.unhexlify(hex_content)
                            payload_str = payload_bytes.decode('utf-16le')
                        except (ValueError, UnicodeDecodeError):
                            pass

                    payload_str = payload_str.strip()
                    transactions.append({
                        "transaction_id": current_txn,
                        "payload": payload_str
                    })
                # Reset for next transaction
                in_txn = False
                current_txn = None
                current_encoding = None
                payload_lines = []
            elif line.startswith('ENCODING='):
                current_encoding = line.split('=', 1)[1]
                payload_lines = []  # Reset payload on new encoding
            else:
                # Payload line (not ENCODING, not END)
                payload_lines.append(line)
        else:
            if line.startswith('[WAL_START] TXN='):
                in_txn = True
                current_txn = line.split('=', 1)[1]
                current_encoding = None
                payload_lines = []

    return transactions

def main():
    if len(sys.argv) < 2:
        print(json.dumps([]))
    else:
        filepath = sys.argv[1]
        result = parse_wal(filepath)
        print(json.dumps(result))

if __name__ == '__main__':
    main()
