#include <cmath>
#include <map>
#include <iomanip>

int main(int argc, char* argv[]) {
    // Check if p is provided as argument
    if (argc < 2) {
        std::cerr << "Error: Missing polynomial power argument (p)" << std::endl;
        return 1;
    }

    int p = std::stoi(argv[1]);

    // Check if data.csv exists
    std::ifstream infile("/home/user/data.csv");
    if (!infile.is_open()) {
        std::cerr << "Error: Cannot open /home/user/data.csv" << std::endl;
        return 1;
    }

    // Map to store aggregated embeddings by id
    // Key: id, Value: pair of (S1, S2) sums
    std::map<int, std::pair<double, double>> aggregates;

    // Read file and compute embeddings
    std::string line;
    while (std::getline(infile, line)) {
        // Skip empty lines
        if (line.empty()) continue;

        // Parse the line: id,v1,v2
        std::string id_str, v1_str, v2_str;

        // Find commas
        size_t comma1 = line.find(',');
        size_t comma2 = line.find(',', comma1 + 1);

        if (comma1 == std::string::npos || comma2 == std::string::npos) {
            std::cerr << "Error: Invalid line format" << std::endl;
            continue;
        }

        id_str = line.substr(0, comma1);
        v1_str = line.substr(comma1 + 1, comma2 - comma1 - 1);
        v2_str = line.substr(comma2 + 1);

        // Parse values
        int id = std::stoi(id_str);
        double v1 = std::stod(v1_str);
        double v2 = std::stod(v2_str);

        // Compute polynomial embeddings
        double e1 = std::pow(v1, p);
        double e2 = std::pow(v2, p);

        // Add to aggregates
        if (aggregates.find(id) == aggregates.end()) {
            aggregates[id] = {0.0, 0.0};
        }
        aggregates[id].first += e1;
        aggregates[id].second += e2;
    }

    infile.close();

    // Compute global score: sum of L2 norms of aggregated vectors
    double score = 0.0;
    for (auto const& [id, vals] : aggregates) {
        double s1 = vals.first;
        double s2 = vals.second;
        double l2_norm = std::sqrt(s1 * s1 + s2 * s2);
        score += l2_norm;
    }

    // Print score with 4 decimal places
    std::cout << std::fixed << std::setprecision(4) << score << std::endl;

    return 0;
}
