// Function to read config file
std::map<std::string, std::string> readConfig(const std::string& path) {
    std::map<std::string, std::string> config;
    std::ifstream file(path);
    if (!file.is_open()) {
        std::cerr << "Failed to open config file: " << path << std::endl;
        return config;
    }

    std::string line;
    while (std::getline(file, line)) {
        size_t pos = line.find('=');
        if (pos != std::string::npos) {
            std::string key = line.substr(0, pos);
            std::string value = line.substr(pos + 1);
            // Trim whitespace
            while (!key.empty() && (key.back() == ' ' || key.back() == '\t')) key.pop_back();
            while (!value.empty() && (value.front() == ' ' || value.front() == '\t')) value = value.substr(1);
            if (!key.empty()) {
                config[key] = value;
            }
        }
    }
    return config;
}

// Function to convert UTF-16LE to UTF-8
std::string utf16leToUtf8(const uint8_t* utf16leData, size_t length) {
    std::string result;
    size_t i = 0;
    while (i < length) {
        uint16_t codeUnit = (uint16_t(utf16leData[i+1]) << 8) | uint16_t(utf16leData[i]);
        i += 2;

        if (codeUnit < 0x80) {
            result += static_cast<char>(codeUnit);
        } else if (codeUnit < 0x800) {
            result += static_cast<char>(0xC0 | (codeUnit >> 6));
            result += static_cast<char>(0x80 | (codeUnit & 0x3F));
        } else {
            result += static_cast<char>(0xE0 | (codeUnit >> 12));
            result += static_cast<char>(0x80 | ((codeUnit >> 6) & 0x3F));
            result += static_cast<char>(0x80 | (codeUnit & 0x3F));
        }
    }
    return result;
}

