    // Vector to store chunk indices [chunk_num, record_count]
    std::vector<std::pair<std::string, int>> chunkIndex;

    uint8_t* buffer = new uint8_t[maxChunkSize + 1024]; // Extra buffer for safety
    size_t bufferUsed = 0;
    int currentChunk = 1;
    int recordsInCurrentChunk = 0;

    std::string utf8ChunkContent;

    while (dumpFile.peek() != EOF) {
        // Read 4-byte little-endian length
        uint32_t length;
        dumpFile.read(reinterpret_cast<char*>(&length), 4);
        if (!dumpFile.good()) {
            std::cerr << "Error reading length field" << std::endl;
            delete[] buffer;
            return 1;
        }

        // Read UTF-16LE data
        uint8_t* utf16leData = new uint8_t[length];
        dumpFile.read(reinterpret_cast<char*>(utf16leData), length);
