                    outFile.close();
                }

                chunkIndex.push_back({filename, recordsInCurrentChunk});
                utf8ChunkContent.clear();
                currentChunk++;
                recordsInCurrentChunk = 0;
            }

            // Start new chunk with current record
            bufferUsed = 0;
        }

        // Append UTF-8 text to current chunk buffer
        utf8ChunkContent += utf8Text;
        recordsInCurrentChunk++;

        // Cleanup
        delete[] utf16leData;
    }

    // Don't forget to handle the last chunk
    if (!utf8ChunkContent.empty() || currentChunk == 1) {
        std::ostringstream chunkFilename;
