#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define REF_DIM 5
#define THRESHOLD 0.85

float ref[REF_DIM] = {0.500, -0.200, 0.100, 0.800, 0.300};

double dot_product(float *a, float *b, int n) {
    double sum = 0.0;
    for (int i = 0; i < n; i++) {
        sum += (double)a[i] * b[i];
    }
    return sum;
}

double norm(float *a, int n) {
    double sum = 0.0;
    for (int i = 0; i < n; i++) {
        sum += (double)a[i] * a[i];
    }
    return sqrt(sum);
}

double cosine_similarity(float *v1, float *v2, int n) {
    return dot_product(v1, v2, n) / (norm(v1, n) * norm(v2, n));
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        return 1;
    }

    FILE *fp = fopen(argv[1], "r");
    if (!fp) {
        return 1;
    }

    // Skip header line
    char header[1024];
    if (fgets(header, sizeof(header), fp) == NULL) {
        fclose(fp);
        return 0;
    }

    // Read data lines
    char line[1024];
    while (fgets(line, sizeof(line), fp) != NULL) {
        float v[REF_DIM];
        // Parse: id,f1,f2,f3,f4,f5 - extract f1-f5
        int idx = 0;
        char *token = strtok(line, ",\n\r");
        // Skip id (first token)
        if (token != NULL) { /* skip id */ }
        token = strtok(NULL, ",\n\r");
        if (token) v[0] = atof(token);
        token = strtok(NULL, ",\n\r");
        if (token) v[1] = atof(token);
        token = strtok(NULL, ",\n\r");
        if (token) v[2] = atof(token);
        token = strtok(NULL, ",\n\r");
        if (token) v[3] = atof(token);
        token = strtok(NULL, ",\n\r");
        if (token) v[4] = atof(token);

        double sim = cosine_similarity(v, ref, REF_DIM);
        if (sim >= THRESHOLD) {
            fclose(fp);
            return 1;
        }
    }

    fclose(fp);
    return 0;
}
