// readEmbeddings reads a CSV file and returns a 2D slice of floats
// Expected format: rows x columns (no header)
func readEmbeddings(filename string) ([][]float64, error) {
	file, err := os.Open(filename)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	reader := csv.NewReader(file)
	var embeddings [][]float64

	for {
