			if err != nil {
				return nil, err
			}
		}
		embeddings = append(embeddings, row)
	}

	return embeddings, nil
}

// readProjection reads a CSV file and returns a 2D slice of floats
// Expected format: rows x columns (no header)
func readProjection(filename string) ([][]float64, error) {
	file, err := os.Open(filename)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	reader := csv.NewReader(file)
	var projection [][]float64

	for {
		record, err := reader.Read()
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}

		row := make([]float64, len(record))
		for i, val := range record {
			row[i], err = strconv.ParseFloat(val, 64)
			if err != nil {
				return nil, err
			}
		}
		projection = append(projection, row)
	}

	return projection, nil
}

// multiplyMatrices performs matrix multiplication: A (m x n) * B (n x p) = C (m x p)
func multiplyMatrices(A [][]float64, B [][]float64) [][]float64 {
	m := len(A)
	n := len(A[0])
	// n should equal len(B[0])
	p := len(B[0])

	C := make([][]float64, m)
	for i := 0; i < m; i++ {
		C[i] = make([]float64, p)
		for j := 0; j < p; j++ {
			sum := 0.0
			for k := 0; k < n; k++ {
				sum += A[i][k] * B[k][j]
			}
			C[i][j] = sum
		}
	}
	return C
}

// generateRecommendations finds the top 2 nearest neighbors for each document
func generateRecommendations(reduced [][]float64) map[string][]int {
	numDocs := len(reduced)
	recommendations := make(map[string][]int)

	for i := 0; i < numDocs; i++ {
		// Find top 2 nearest neighbors
		type neighbor struct {
			index int
			dist  float64
		}
		type distSorter struct {
			idx int
			d   float64
		}

		var neighbors []distSorter
		for j := 0; j < numDocs; j++ {
			if i == j {
				continue // Skip self
			}
			dist := euclideanDistance(reduced[i], reduced[j])
			neighbors = append(neighbors, distSorter{idx: j, d: dist})
		}

		// Sort by distance
		for k := 0; k < len(neighbors)-1; k++ {
			for l := k + 1; l < len(neighbors); l++ {
				if neighbors[l].d < neighbors[k].d {
					neighbors[k], neighbors[l] = neighbors[l], neighbors[k]
				}
			}
		}

		// Take top 2
		top2 := []int{neighbors[0].idx, neighbors[1].idx}
		recommendations[strconv.Itoa(i)] = top2
	}

	return recommendations
}

// euclideanDistance calculates the Euclidean distance between two vectors
func euclideanDistance(v1, v2 []float64) float64 {
	sum := 0.0
	for i := range v1 {
		diff := v1[i] - v2[i]
		sum += diff * diff
	}
	return math.Sqrt(sum)
}

// writeRecommendations writes the recommendations map to a JSON file
func writeRecommendations(filename string, data map[string][]int) error {
	file, err := os.Create(filename)
	if err != nil {
		return err
	}
	defer file.Close()

	encoder := json.NewEncoder(file)
	encoder.SetIndent("", "  ")
	return encoder.Encode(data)
}
